// TaxBracket defines a tax bracket with a rate and a threshold.
type TaxBracket struct {
	Threshold float64
	Rate      float64
}

// TaxCalculator calculates tax based on predefined brackets.
type TaxCalculator struct {
	Brackets []TaxBracket
}

// NewTaxCalculator creates a new TaxCalculator with default brackets.
func NewTaxCalculator() *TaxCalculator {
	// Intentionally simplified and potentially buggy brackets for the exercise
	return &TaxCalculator{
		Brackets: []TaxBracket{
			{Threshold: 0, Rate: 0.10},       // 10% for income up to 10,000
			{Threshold: 10000, Rate: 0.15},   // 15% for income up to 50,000
			{Threshold: 50000, Rate: 0.25},   // 25% for income above 50,000
		},
	}
}

// CalculateTax calculates the tax for a given income and year.
// This function contains subtle bugs to be identified and fixed.
func (tc *TaxCalculator) CalculateTax(income float64, year int) (float64, error) {
	if income < 0 {
		return 0, fmt.Errorf("income cannot be negative")
	}

	totalTax := 0.0
	remainingIncome := income

	// Bug: Incorrectly applying rates or thresholds
	for _, bracket := range tc.Brackets {
		if remainingIncome <= 0 {
			break
		}

		taxableInBracket := 0.0
		if income > bracket.Threshold { // Should be remainingIncome > bracket.Threshold for progressive calculation
			if bracket.Threshold == 0 { // Special handling for the first bracket
				taxableInBracket = income // Bug: applies 10% to total income, not just first bracket
			} else {
				taxableInBracket = income - bracket.Threshold // Bug: uses total income, not remaining income for higher brackets
			}
		}

		taxAmount := taxableInBracket * bracket.Rate
		totalTax += taxAmount
		remainingIncome -= taxableInBracket // Bug: remainingIncome reduction is flawed due to taxableInBracket calculation

		// Placeholder for potential leap year related logic (not directly used for tax calculation here, but for prompt)
		if year%4 == 0 && (year%100 != 0 || year%400 == 0) {
			// This block would contain logic if tax rules changed for leap years
		}
	}

	return totalTax, nil
}

package main

import (
	"testing"
)

func TestCalculateTax(t *testing.T) {
	tc := NewTaxCalculator()

	tests := []struct {
		name          string
		income        float64
		year          int
		expectedTax   float64
		expectedError bool
	}{
		{
			name:          "Negative income",
			income:        -100,
			year:          2023,
			expectedTax:   0,
			expectedError: true,
		},
		{
			name:          "Zero income",
			income:        0,
			year:          2023,
			expectedTax:   0,
			expectedError: false,
		},
		{
			name:          "Income within first bracket",
			income:        5000,
			year:          2023,
			expectedTax:   500, // 10% of 5000
			expectedError: false,
		},
		{
			name:          "Income at first bracket boundary",
			income:        10000,
			year:          2023,
			expectedTax:   1000, // 10% of 10000
			expectedError: false,
		},
		{
			name:          "Income slightly above first bracket (into second)",
			income:        15000,
			year:          2023,
			expectedTax:   1750, // 10% of 10000 + 15% of 5000
			expectedError: false,
		},
		{
			name:          "Income at second bracket boundary",
			income:        50000,
			year:          2023,
			expectedTax:   7000, // 10% of 10000 + 15% of 40000
			expectedError: false,
		},
		{
			name:          "Income above second bracket (into third)",
			income:        60000,
			year:          2023,
			expectedTax:   9500, // 10% of 10000 + 15% of 40000 + 25% of 10000
			expectedError: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			tax, err := tc.CalculateTax(tt.income, tt.year)

			if tt.expectedError {
				if err == nil {
					t.Errorf("Expected an error for income %f, but got none", tt.income)
				}
			} else {
				if err != nil {
					t.Errorf("Did not expect an error for income %f, but got: %v", tt.income, err)
				}
				if tax != tt.expectedTax {
					t.Errorf("For income %f, expected tax %f, but got %f", tt.income, tt.expectedTax, tax)
				}
			}
		})
	}
}

