	if income < 0 {
		return 0, fmt.Errorf("income cannot be negative")
	}

	totalTax := 0.0

	for _, bracket := range tc.Brackets {
		// If the income is below the current bracket's minimum, this bracket (and higher ones) don't apply.
		if income <= bracket.Min {
			continue
		}

		// Determine the portion of income that falls into this specific bracket's band.
		// This is the minimum of (income, bracket.Max) minus bracket.Min.

		// The upper bound for taxation in this bracket is either the income itself or the bracket's max.
