			income:        60000,
			year:          2024, // A leap year
			expectedTax:   9500, // Same expected tax as year doesn't affect calculation
			expectedError: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
